def treffer(text, pattern):
    text = text.lower()
    pattern = pattern.lower()
    return sum(text.startswith(pattern, i) for i in range(len(text)))

print(treffer("ababa", "aba"))
print(treffer("xxBABaba", "bab"))

def count_flags(text, patterns):
    text = text.casefold()
    return sum(text.count(pattern.casefold()) for pattern in patterns)

print(count_flags("Warnung: TEST test", ["test", "warn"]))
print(count_flags("abab", ["ab", "ba"]))
